INSERT INTO `blog` (`judul`,`slug`,`user_id`,`konten`,`excerpt`,`gambar_utama`,`status`,`created_at`,`updated_at`) VALUES ('Secure Your Growing Business','secure-your-growing-business',NULL,'<script type="text/javascript" src="https://widgets.ziftsolutions.com/dell.ziftsolutions.com/js/8a9983dc6cae1b21016cae52873b17c8" charset="utf-8"></script>

