INSERT INTO `blog` (`judul`,`slug`,`user_id`,`konten`,`excerpt`,`gambar_utama`,`status`,`created_at`,`updated_at`) VALUES ('Apa Itu Smart Hospital? Pengertian, Fungsi, dan Solusi di Era Digital','apa-itu-smart-hospital-pengertian-fungsi-dan-solusi-di-era-digital',NULL,'Antrean panjang, proses administrasi yang rumit, hingga data pasien yang tidak terorganisir masih menjadi tantangan di banyak rumah sakit saat ini. Di tengah tuntutan layanan yang serba cepat, kondisi <i data-path-to-node="2" data-index-in-node="201">Smart hospital saat ini</i> tentu menjadi perhatian besar, di mana implementasi <i data-path-to-node="2" data-index-in-node="277">IT Solutions</i> yang tepat sangat dibutuhkan.

