INSERT INTO `blog` (`judul`,`slug`,`user_id`,`konten`,`excerpt`,`gambar_utama`,`status`,`created_at`,`updated_at`) VALUES ('Sapta Tunas Teknologi Raih Penghargaan Penyedia Barang dan Jasa pada Vendor Gathering PT Angkasa Pura Indonesia Tahun 2026','sapta-tunas-teknologi-raih-penghargaan-penyedia-barang-dan-jasa-pada-vendor-gathering-pt-angkasa-pura-indonesia-tahun-2026',NULL,'Sapta Tunas Teknologi kembali memperoleh apresiasi atas kontribusi dan kinerja yang diberikan dalam mendukung kebutuhan operasional dan pengadaan di lingkungan PT. Angkasa Pura Indonesia. Penghargaan ini diberikan dalam acara Vendor Gathering Tahun 2026 bertema <em>Infinite Synergy</em> yang diselenggarakan oleh PT. Angkasa Pura Indonesia.

